1→/**
 * HU-10-01 — Pantalla de login.
 *
 * Reglas implementadas acá:
 *  RN-1  campos `email` y `password` obligatorios; el botón queda deshabilitado si alguno
 *        está vacío o hay un envío en curso.
 *  RN-2  anti doble submit: durante una solicitud en curso el segundo intento se ignora.
 *  RN-3  ante 200 se establece la sesión (token + `expiresAt`, persistidos por
 *        `SessionProvider`) y se navega a la vista de trading. El token no se muestra.
10→ *  RN-4  `INVALID_CREDENTIALS` ⇒ mensaje genérico que no revela si el email existe; se
 *        limpia la contraseña y se permanece en la pantalla.
 *  RN-5  `VALIDATION_ERROR` ⇒ detalle por campo derivado de `details.issues`.
 *  RN-6  `RATE_LIMITED` ⇒ botón deshabilitado y cuenta regresiva de
 *        `details.retryAfterSeconds`; al vencer, se rehabilita.
 *  RN-7  aviso de "sesión expirada" cuando se llegó acá por un `UNAUTHENTICATED` de una
 *        llamada protegida (lo deja `SessionProvider`).
 *  RN-8  fallo de red o `INTERNAL_ERROR` ⇒ mensaje no técnico y opción de reintentar, sin
 *        perder el email ingresado ni filtrar detalles del error.
 *  RN-9  si ya hay sesión válida, se redirige a trading sin pedir credenciales.
20→ *  RN-10 todo error se discrimina por `code`, nunca por `message`.
 *  RN-11 la validación de la sesión persistida ocurre en `SessionProvider` (`GET /me`).
 */
import { useCallback, useEffect, useMemo, useRef, useState, type FormEvent } from 'react';
import { Navigate } from 'react-router-dom';
import { login } from '../api/auth';
import {
  ApiError,
  MESSAGE_CONNECTION,
  MESSAGE_INVALID_CREDENTIALS,
30→  MESSAGE_SESSION_EXPIRED,
  messageForCode,
  type ErrorCode,
  type ValidationIssue,
} from '../api/errors';
import { useSession } from '../session/SessionProvider';
import { TRADING_ROUTE } from './routes';

/**
 * Espera por defecto si un `RATE_LIMITED` llegara sin `details.retryAfterSeconds` ni header
40→ * `Retry-After`, **o con una espera de `0`**. El contrato siempre envía una espera positiva
 * (HU-09-02 RN-12, HU-01-02 RN-9: el rechazo implica que la ventana sigue vigente); es sólo
 * una red de seguridad para no dejar el botón habilitado contra un límite vigente, como
 * manda RN-6. El mismo criterio rige en el cliente mobile (paridad de RG-6 de la épica 11).
 */
const FALLBACK_RETRY_AFTER_SECONDS = 60;

type FormError =
  | { kind: 'CREDENTIALS' }
  | { kind: 'VALIDATION'; issues: ValidationIssue[] }
50→  | { kind: 'RATE_LIMITED' }
  | { kind: 'CONNECTION' }
  | { kind: 'OTHER'; code: ErrorCode };

function issuesForField(issues: ValidationIssue[], field: string): string[] {
  return issues.filter((issue) => issue.field === field).map((issue) => issue.message);
}

function generalIssues(issues: ValidationIssue[]): string[] {
  return issues
60→    .filter((issue) => issue.field !== 'email' && issue.field !== 'password')
    .map((issue) => issue.message);
}

export function LoginPage(): React.JSX.Element {
  const { state, notice, signIn, clearNotice } = useSession();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [submitting, setSubmitting] = useState(false);
70→  const [error, setError] = useState<FormError | null>(null);
  /** Instante (epoch ms) hasta el que el reintento está bloqueado por rate limit (RN-6). */
  const [retryAt, setRetryAt] = useState<number | null>(null);
  const [remainingSeconds, setRemainingSeconds] = useState(0);

  // El ref cierra la ventana entre dos clicks del mismo tick: el estado `submitting` se
  // aplica en el siguiente render, el ref es inmediato (RN-2).
  const inFlightRef = useRef(false);

  // ------------------------------------------------------------- cuenta regresiva (RN-6)
80→  useEffect(() => {
    if (retryAt === null) return;
    const tick = (): void => {
      const left = Math.max(0, Math.ceil((retryAt - Date.now()) / 1000));
      setRemainingSeconds(left);
      // Transcurrido el lapso indicado, el botón se rehabilita (AT-10-01-06).
      if (left === 0) setRetryAt(null);
    };
    tick();
    const timer = setInterval(tick, 250);
90→    return () => clearInterval(timer);
  }, [retryAt]);

  const rateLimited = retryAt !== null;
  const fieldsComplete = email.trim() !== '' && password !== '';
  // RN-1: deshabilitado con algún campo vacío o con un envío en curso. RN-6 agrega la espera
  // por rate limit.
  const submitDisabled = !fieldsComplete || submitting || rateLimited;

  const emailIssues = useMemo(
100→    () => (error?.kind === 'VALIDATION' ? issuesForField(error.issues, 'email') : []),
    [error],
  );
  const passwordIssues = useMemo(
    () => (error?.kind === 'VALIDATION' ? issuesForField(error.issues, 'password') : []),
    [error],
  );
  const otherIssues = useMemo(
    () => (error?.kind === 'VALIDATION' ? generalIssues(error.issues) : []),
    [error],
110→  );

  const submit = useCallback(async (): Promise<void> => {
    // RN-2 (anti doble submit) y RN-6 (espera vigente): el intento se ignora sin disparar
    // ninguna llamada a la API.
    if (inFlightRef.current || retryAt !== null) return;
    if (!(email.trim() !== '' && password !== '')) return; // RN-1: sin campos no hay llamada

    inFlightRef.current = true;
    setSubmitting(true);
120→    clearNotice();
    setError(null);

    try {
      const session = await login({ email, password });
      // RN-3: se establece la sesión y se navega a la vista de trading. La navegación la
      // resuelve el `<Navigate>` de abajo al pasar el estado a `authenticated`.
      signIn(session);
    } catch (caught) {
      if (caught instanceof ApiError) {
130→        // RN-10: se discrimina por `code`, nunca por el `message` del servidor.
        switch (caught.code) {
          case 'INVALID_CREDENTIALS':
            // RN-4: mensaje genérico; la contraseña se limpia y el email queda para reintentar.
            setPassword('');
            setError({ kind: 'CREDENTIALS' });
            break;
          case 'VALIDATION_ERROR':
            setError({ kind: 'VALIDATION', issues: caught.issues });
            break;
140→          case 'RATE_LIMITED': {
            const informed = caught.retryAfterSeconds;
            // Un 429 que dijera "esperá 0 s" se contradice a sí mismo: RN-6 manda deshabilitar
            // el reintento, así que se trata igual que una espera no informada.
            const seconds = informed !== null && informed > 0 ? informed : FALLBACK_RETRY_AFTER_SECONDS;
            setError({ kind: 'RATE_LIMITED' });
            setRemainingSeconds(seconds);
            if (seconds > 0) setRetryAt(Date.now() + seconds * 1000);
            break;
          }
150→          case 'INTERNAL_ERROR':
            // RN-8: mensaje no técnico, sin filtrar detalles del error.
            setError({ kind: 'CONNECTION' });
            break;
          default:
            setError({ kind: 'OTHER', code: caught.code });
        }
      } else {
        // Falla de red o respuesta fuera del contrato (RN-8).
        setError({ kind: 'CONNECTION' });
160→      }
    } finally {
      inFlightRef.current = false;
      setSubmitting(false);
    }
  }, [clearNotice, email, password, retryAt, signIn]);

  const onSubmit = useCallback(
    (event: FormEvent<HTMLFormElement>): void => {
      event.preventDefault();
170→      void submit();
    },
    [submit],
  );

  // ------------------------------------------------------------------------- render
  if (state.status === 'checking') {
    // RN-11: mientras se revalida el token persistido con `GET /me` no se pide credenciales.
    return (
      <main className="page page--centered">
180→        <p role="status">Validando sesión…</p>
      </main>
    );
  }

  // RN-9: con sesión válida no se vuelve a pedir credenciales (AT-10-01-01, AT-10-01-09).
  if (state.status === 'authenticated') return <Navigate to={TRADING_ROUTE} replace />;

  return (
    <main className="page page--centered">
190→      <form className="card login" onSubmit={onSubmit} noValidate aria-labelledby="login-title">
        <h1 id="login-title">Ingresar</h1>
        <p className="muted">Exchange ETH/USDC · Sepolia</p>

        {notice === 'SESSION_EXPIRED' && (
          // RN-7: se llegó acá por un `UNAUTHENTICATED` en una llamada protegida.
          <p className="alert alert--warning" role="alert">
            {MESSAGE_SESSION_EXPIRED}
          </p>
        )}
200→        {notice === 'CONNECTION_ERROR' && (
          <p className="alert alert--warning" role="alert">
            {MESSAGE_CONNECTION}
          </p>
        )}

        <label htmlFor="email">Email</label>
        <input
          id="email"
          name="email"
210→          type="email"
          autoComplete="username"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          aria-invalid={emailIssues.length > 0}
          aria-describedby={emailIssues.length > 0 ? 'email-error' : undefined}
        />
        {emailIssues.length > 0 && (
          <ul className="field-error" id="email-error">
            {emailIssues.map((message) => (
220→              <li key={message}>{message}</li>
            ))}
          </ul>
        )}

        <label htmlFor="password">Contraseña</label>
        <input
          id="password"
          name="password"
          type="password"
230→          autoComplete="current-password"
          value={password}
          onChange={(event) => setPassword(event.target.value)}
          aria-invalid={passwordIssues.length > 0}
          aria-describedby={passwordIssues.length > 0 ? 'password-error' : undefined}
        />
        {passwordIssues.length > 0 && (
          <ul className="field-error" id="password-error">
            {passwordIssues.map((message) => (
              <li key={message}>{message}</li>
240→            ))}
          </ul>
        )}

        <button type="submit" disabled={submitDisabled} aria-busy={submitting}>
          {submitting ? 'Ingresando…' : 'Ingresar'}
        </button>

        {error?.kind === 'CREDENTIALS' && (
          <p className="alert alert--error" role="alert">
250→            {MESSAGE_INVALID_CREDENTIALS}
          </p>
        )}

        {error?.kind === 'VALIDATION' && (
          <div className="alert alert--error" role="alert">
            <p>{messageForCode('VALIDATION_ERROR')}</p>
            {otherIssues.length > 0 && (
              <ul>
                {otherIssues.map((message) => (
260→                  <li key={message}>{message}</li>
                ))}
              </ul>
            )}
          </div>
        )}

        {error?.kind === 'RATE_LIMITED' && (
          <p className="alert alert--error" role="alert">
            {remainingSeconds > 0
270→              ? `Demasiados intentos. Esperá ${remainingSeconds} segundos e intentá de nuevo.`
              : 'Ya podés reintentar.'}
          </p>
        )}

        {error?.kind === 'CONNECTION' && (
          <div className="alert alert--error" role="alert">
            <p>{MESSAGE_CONNECTION}</p>
            {/* RN-8: se ofrece reintentar sin perder el email ingresado. */}
            <button type="button" onClick={() => void submit()} disabled={submitDisabled}>
280→              Reintentar
            </button>
          </div>
        )}

        {error?.kind === 'OTHER' && (
          <p className="alert alert--error" role="alert">
            {messageForCode(error.code)}
          </p>
        )}
290→      </form>
    </main>
  );
}

