  'INVALID_CREDENTIALS',
  'ACCOUNT_NOT_FOUND',
  // 3.7 Genéricos / sistema
  'CONFLICT',
  'INTERNAL_ERROR',
] as const;

export type ErrorCode = (typeof ERROR_CODES)[number];

const ERROR_CODE_SET: ReadonlySet<string> = new Set<string>(ERROR_CODES);

export function isErrorCode(value: unknown): value is ErrorCode {
  return typeof value === 'string' && ERROR_CODE_SET.has(value);
}

/** Causa individual de un `VALIDATION_ERROR` (`details.issues`, HU-09-05 RN-5). */
export type ValidationIssue = { field?: string; message: string };

/** Error de dominio devuelto por la API con el envelope del catálogo. */
export class ApiError extends Error {
  readonly code: ErrorCode;
  readonly httpStatus: number;
  readonly details: Record<string, unknown>;
  /** Valor del header `Retry-After` (segundos) cuando la respuesta lo trajo. */
  readonly retryAfterHeaderSeconds: number | null;

  constructor(
    code: ErrorCode,
    httpStatus: number,
    details: Record<string, unknown> = {},
    retryAfterHeaderSeconds: number | null = null,
  ) {
    // El `message` del Error es interno (nunca se muestra tal cual): la UI usa `code`.
    super(`ApiError ${code} (${httpStatus})`);
    this.name = 'ApiError';
    this.code = code;
    this.httpStatus = httpStatus;
    this.details = details;
    this.retryAfterHeaderSeconds = retryAfterHeaderSeconds;
  }

  /**
   * Causas por campo de un `VALIDATION_ERROR` (HU-10-01 RN-5). Se aceptan sólo issues con
   * `message` string; el `field` es opcional (una causa puede no referirse a un campo).
   */
  get issues(): ValidationIssue[] {
    const raw = this.details.issues;
    if (!Array.isArray(raw)) return [];
    const issues: ValidationIssue[] = [];
    for (const item of raw) {
      if (typeof item !== 'object' || item === null) continue;
      const candidate = item as { field?: unknown; message?: unknown };
      if (typeof candidate.message !== 'string') continue;
      issues.push(
        typeof candidate.field === 'string'
          ? { field: candidate.field, message: candidate.message }
          : { message: candidate.message },
      );
    }
    return issues;
  }

  /**
   * Segundos de espera de un `RATE_LIMITED` (HU-10-01 RN-6). `retryAfterSeconds` es un
   * **entero JSON** (es un conteo, no un monto: `convenciones-monetarias.md` §5), así que se
   * exige entero no negativo; un valor con otra forma se ignora y se cae al header
   * `Retry-After` (HU-09-02 RN-12), que la API envía junto al `RATE_LIMITED`.
   */
  get retryAfterSeconds(): number | null {
    const raw = this.details.retryAfterSeconds;
    if (typeof raw === 'number' && Number.isInteger(raw) && raw >= 0) return raw;
    return this.retryAfterHeaderSeconds;
  }
}

/**
 * Falla de transporte: el servidor no respondió (red caída, DNS, CORS, timeout) o respondió
 * algo que **no** es el contrato (cuerpo no JSON, envelope sin `code` del catálogo). Se trata
 * igual que un fallo de red a efectos de UX (HU-10-01 RN-8): mensaje no técnico y reintento.
 */
export class TransportError extends Error {
  constructor(reason: string) {
    super(`TransportError: ${reason}`);
    this.name = 'TransportError';
  }
}

/**
 * Texto para el usuario derivado del `code` (RNE-3, HU-10-01 RN-10).
 *
 * `INVALID_CREDENTIALS` usa un mensaje **genérico** que no revela si el email existe
 * (HU-10-01 RN-4, coherente con `modelo-de-errores.md` §3.6 y HU-01-02 RN-2): es el mismo
 * texto para "email inexistente" y para "contraseña incorrecta".
 */
export const MESSAGE_INVALID_CREDENTIALS = 'Email o contraseña incorrectos';
export const MESSAGE_CONNECTION = 'No se pudo conectar, reintentá';
export const MESSAGE_SESSION_EXPIRED = 'Tu sesión expiró, ingresá nuevamente';

export function messageForCode(code: ErrorCode): string {
  switch (code) {
    case 'INVALID_CREDENTIALS':
      return MESSAGE_INVALID_CREDENTIALS;
    case 'UNAUTHENTICATED':
      return MESSAGE_SESSION_EXPIRED;
    case 'VALIDATION_ERROR':
      return 'Revisá los datos ingresados.';
    case 'RATE_LIMITED':
      return 'Demasiados intentos. Esperá unos segundos e intentá de nuevo.';
    case 'UNAUTHORIZED':
      return 'No tenés permiso para esta operación.';
    case 'NOT_FOUND':
    case 'METHOD_NOT_ALLOWED':
    case 'INTERNAL_ERROR':
      // Errores no accionables por el usuario: mensaje no técnico, sin filtrar detalles
      // del error (HU-10-01 RN-8).
      return MESSAGE_CONNECTION;
    default:
      return 'No se pudo completar la operación. Reintentá.';
  }
}

