1→/**
 * Persistencia del lado del cliente del token Bearer y su expiración (HU-10-01 RN-3).
 *
 * El contrato no emite cookies de sesión: el token viaja en el header `Authorization` y el
 * cliente lo guarda para **sobrevivir recargas**, revalidándolo contra el servidor al cargar
 * la app (RN-11). Se guarda únicamente `{ token, expiresAt }`; el token no se escribe en
 * logs ni se muestra en la UI (RNE-4).
 */

10→export const SESSION_STORAGE_KEY = 'exchange.web.session.v1';

export type PersistedSession = { token: string; expiresAt: string };

/** `localStorage` puede no estar disponible (modo privado, SSR, sandbox): nunca debe romper la app. */
function storage(): Storage | null {
  try {
    return globalThis.localStorage ?? null;
  } catch {
    return null;
20→  }
}

export function loadSession(): PersistedSession | null {
  const store = storage();
  if (store === null) return null;
  let raw: string | null;
  try {
    raw = store.getItem(SESSION_STORAGE_KEY);
  } catch {
30→    return null;
  }
  if (raw === null) return null;
  try {
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== 'object' || parsed === null) return null;
    const candidate = parsed as { token?: unknown; expiresAt?: unknown };
    if (typeof candidate.token !== 'string' || candidate.token === '') return null;
    if (typeof candidate.expiresAt !== 'string' || Number.isNaN(Date.parse(candidate.expiresAt))) {
      return null;
40→    }
    return { token: candidate.token, expiresAt: candidate.expiresAt };
  } catch {
    // Entrada corrupta: equivale a no tener sesión persistida.
    return null;
  }
}

export function saveSession(session: PersistedSession): void {
  const store = storage();
50→  if (store === null) return;
  try {
    store.setItem(SESSION_STORAGE_KEY, JSON.stringify(session));
  } catch {
    // Cuota llena o storage bloqueado: la sesión sigue viva en memoria de la SPA (RN-11).
  }
}

/** Limpia **todo** el estado de sesión local (RN-7, RN-11). */
export function clearSession(): void {
60→  const store = storage();
  if (store === null) return;
  try {
    store.removeItem(SESSION_STORAGE_KEY);
  } catch {
    /* nada que limpiar si el storage no está disponible */
  }
}

/** Chequeo local de expiración previo a la revalidación contra el servidor (RN-11). */
70→export function isExpired(expiresAt: string, now: number = Date.now()): boolean {
  const parsed = Date.parse(expiresAt);
  if (Number.isNaN(parsed)) return true;
  return parsed <= now;
}

