/**
 * Llamadas de autenticación del contrato de la épica 09 (HU-09-01, mapa de endpoints):
 *   POST /api/v1/auth/login  → 200 { token, expiresAt }   (público, HU-01-02)
 *   GET  /api/v1/me          → 200 { accountId, email, status, createdAt }  (Bearer, HU-01-04)
 */
import { apiRequest } from './client';
import { TransportError } from './errors';

export type Credentials = { email: string; password: string };

/** Sesión emitida por el login (HU-01-02 RN-3: token + `expiresAt` ISO-8601 UTC). */
export type IssuedSession = { token: string; expiresAt: string };

/** Perfil propio (HU-01-04 RN-4: sólo identidad, sin secretos ni montos). */
export type Profile = {
  accountId: string;
  email: string;
  status: string;
  createdAt: string;
};

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Inicia sesión. El email se envía tal como lo tipeó el usuario: la normalización
 * (`trim` + `lowercase`) es del servidor (HU-01-02 RN-1), que es la única fuente de verdad
 * (RNE-2). El cliente tampoco valida el formato del email antes de enviar: hacerlo
 * distinguiría "formato inválido" de "inexistente" y filtraría información (HU-01-02 RN-11).
 */
export async function login(credentials: Credentials): Promise<IssuedSession> {
  const payload = await apiRequest<unknown>('/auth/login', {
    method: 'POST',
    body: { email: credentials.email, password: credentials.password },
  });
  if (
    !isPlainObject(payload) ||
    typeof payload.token !== 'string' ||
    payload.token === '' ||
    typeof payload.expiresAt !== 'string' ||
    Number.isNaN(Date.parse(payload.expiresAt))
  ) {
    // Un 200 sin token utilizable no es una sesión: no se asume éxito (RNE-2).
    throw new TransportError('la respuesta de login no incluye un token utilizable');
  }
  return { token: payload.token, expiresAt: payload.expiresAt };
}

