 * Perfil a partir del cuerpo de un `GET /me` exitoso, o `null` si el cuerpo no respeta el
 * contrato de HU-09-01 (mapa de endpoints: `{ accountId, email, status, createdAt }`).
 *
 * Devuelve `null` en vez de lanzar porque la **validez de la sesión** y la **forma del
 * perfil** son decisiones distintas: RN-11 es explícita en que un 200 significa sesión
 * válida. Un cuerpo incompleto sólo deja al cliente sin datos que mostrar.
 */
export function parseProfile(payload: unknown): Profile | null {
  if (
    !isPlainObject(payload) ||
    typeof payload.accountId !== 'string' ||
    typeof payload.email !== 'string' ||
    typeof payload.status !== 'string' ||
    typeof payload.createdAt !== 'string'
  ) {
    return null;
  }
  return {
    accountId: payload.accountId,
    email: payload.email,
    status: payload.status,
    createdAt: payload.createdAt,
  };
}

