 * llamador—, la ausencia del token o su expiración local.
 */
export async function fetchProfile(
  token: string,
  signal?: AbortSignal,
): Promise<{ profile: Profile | null }> {
  const payload = await apiRequest<unknown>('/me', signal === undefined ? { token } : { token, signal });
  return { profile: parseProfile(payload) };
