 * invalide el token en el servidor vía `POST /api/v1/auth/logout`, endpoint que está fuera del
 * alcance de las etapas implementadas. Un botón que sólo limpiara el estado local dejaría el
 * token vivo hasta su TTL, que es justamente lo que esa regla prohíbe.
 */
import { useEffect, useState } from 'react';
import { useSession } from '../session/SessionProvider';
import { parseProfile, type Profile } from '../api/auth';
import { ApiError, MESSAGE_CONNECTION } from '../api/errors';

export function TradingPage(): React.JSX.Element {
  const { state, authorizedFetch } = useSession();
  const initialProfile = state.status === 'authenticated' ? state.profile : null;
  const [profile, setProfile] = useState<Profile | null>(initialProfile);
  const [loadError, setLoadError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      try {
        const result = parseProfile(await authorizedFetch<unknown>('/me'));
        if (!cancelled && result !== null) setProfile(result);
      } catch (error) {
        if (cancelled) return;
        // Un `UNAUTHENTICATED` ya limpió la sesión en `authorizedFetch` (RN-7) y la
        // redirección la hace `RequireSession`; acá sólo queda reportar el resto.
        if (error instanceof ApiError && error.code === 'UNAUTHENTICATED') return;
        setLoadError(MESSAGE_CONNECTION);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [authorizedFetch]);

  return (
    <main className="page">
      <header className="topbar">
        <h1>ETH/USDC</h1>
        {profile !== null && <span className="muted topbar__session">{profile.email}</span>}
