            <dt>Email</dt>
            <dd>{profile.email}</dd>
            <dt>Estado</dt>
            <dd>{profile.status}</dd>
            <dt>Alta</dt>
            <dd>{profile.createdAt}</dd>
          </dl>
        )}
      </section>

      <section className="card">
        <h2>Vista de trading</h2>
        <p>
          El orderbook en vivo, el formulario de orden, las órdenes abiertas, el historial, los
          balances y los depósitos/retiros (HU-10-02 a HU-10-06) no forman parte de esta
          corrida: dependen de las épicas 02 a 08 y de los canales WebSocket de la épica 09,
          que todavía no están implementados en el backend.
        </p>
      </section>
    </main>
  );
}

/**
 * Configuración del cliente.
 *
 * `VITE_API_BASE_URL` es la base del contrato REST de la épica 09 (ruta base `/api/v1`,
 * HU-09-01 RN-1). Por defecto es relativa al origen del cliente, que es lo que sirve el
 * proxy del dev server (ver `vite.config.ts`); apuntarla a un origen absoluto exige CORS
 * habilitado en el backend para el origen del cliente.
 */
const RAW_BASE_URL = import.meta.env.VITE_API_BASE_URL ?? '/api/v1';

/** Base sin barra final, para componer rutas como `${API_BASE_URL}/auth/login`. */
export const API_BASE_URL = RAW_BASE_URL.replace(/\/+$/u, '');

