 *   POST /api/v1/auth/logout     → 204 (HU-01-03)
 *   GET  /api/v1/me              → 200 (HU-01-04, AT-09-01-03)
 *   GET  /api/v1/deposit-address → 200 (HU-06-04)
10→ *   GET  /health                 → health-check operativo (no forma parte del contrato REST)
 *   GET  /internal/deposit-addresses → consulta interna del contrato con la épica 07
 *                                      (HU-06-03 RN-11); no es una ruta pública.
 *
 * Reglas transversales aplicadas acá: envelope uniforme de error (HU-09-05 RN-1),
 * autenticación Bearer y su precedencia sobre cualquier validación (HU-09-02 RN-9),
 * rate limiting (HU-01-01 RN-10, HU-01-02 RN-9, HU-09-02 RN-12), 404/405 (HU-09-01 RN-14).
 */
import { timingSafeEqual } from 'node:crypto';
import { STATUS_CODES } from 'node:http';
20→import Fastify, { type FastifyInstance, type FastifyReply, type FastifyRequest } from 'fastify';
import { AppError, validationError } from '../shared/errors.js';
import {
  ACCOUNT_RATE_LIMIT_MAX,
  ACCOUNT_RATE_LIMIT_WINDOW_MS,
