import type { AccountsService } from '../accounts/accounts-service.js';
import type { SessionService } from '../accounts/sessions.js';
import type { DepositAddressService } from '../wallet/deposit-address-service.js';
import type { AuditLog } from '../shared/audit-log.js';
import type { ChainStatus } from '../infra/rpc.js';
40→
declare module 'fastify' {
  interface FastifyRequest {
    accountId?: string;
    /** Token Bearer tal como lo presentó el cliente (lo fija el hook `authenticate`). */
    sessionToken?: string;
  }
}

export type AppDeps = {
50→  config: Config;
  accounts: AccountsService;
  sessions: SessionService;
  depositAddresses: DepositAddressService;
  /** Log de auditoría interno de eventos de autenticación (RNE-9). */
  audit: AuditLog;
  /** Estado del nodo JSON-RPC configurado (se refresca en segundo plano). */
  chainStatus: () => ChainStatus;
};

60→/** Rutas conocidas y sus verbos, para distinguir 404 (ruta inexistente) de 405 (verbo). */
const KNOWN_ROUTES: Array<{ path: string; methods: string[] }> = [
  { path: '/api/v1/auth/register', methods: ['POST'] },
  { path: '/api/v1/auth/login', methods: ['POST'] },
  { path: '/api/v1/auth/logout', methods: ['POST'] },
  { path: '/api/v1/me', methods: ['GET'] },
  { path: '/api/v1/deposit-address', methods: ['GET'] },
  { path: '/health', methods: ['GET'] },
  { path: '/internal/deposit-addresses', methods: ['GET'] },
];
70→
function normalizePath(url: string): string {
  const path = url.split('?')[0] ?? '/';
  return path.length > 1 && path.endsWith('/') ? path.slice(0, -1) : path;
}

function clientOrigin(request: FastifyRequest): string {
  return request.ip ?? 'desconocido';
}

80→/**
 * Valores de un parámetro de query, normalizados siempre a lista de strings.
 *
 * Necesario porque Fastify entrega un **array** cuando el parámetro viene repetido
 * (`?chainId=1&chainId=1`): una guarda `typeof raw === 'string'` no aplicaría y la
 * validación quedaría salteada por completo. Todo valor presente se evalúa.
 */
function queryValues(raw: unknown): string[] {
  if (typeof raw === 'string') return [raw];
  if (Array.isArray(raw)) return raw.map((value) => (typeof value === 'string' ? value : String(value)));
90→  return [];
}

/** Comparación de credenciales en tiempo constante (no filtra el prefijo correcto). */
function timingSafeEquals(a: string, b: string): boolean {
  const left = Buffer.from(a, 'utf8');
  const right = Buffer.from(b, 'utf8');
  if (left.length !== right.length) return false;
  return timingSafeEqual(left, right);
}
