function rateLimited(retryAfterSeconds: number): AppError {
  return new AppError(
    'RATE_LIMITED',
    'Se superó el límite de solicitudes permitido; reintentá más tarde.',
    { retryAfterSeconds },
    { 'Retry-After': String(retryAfterSeconds) },
