}

110→/**
 * `NOT_FOUND` (404) de una ruta inexistente (HU-09-01 RN-14, HU-09-05 RN-10). Constructor
 * único para que todos los caminos que lo producen (el 404-handler y los errores de
 * framework, que ocurren antes del ruteo) devuelvan exactamente el mismo `details`
 * (modelo-de-errores.md §3.2: el recurso afectado sólo se expone dentro de `details`).
 */
function notFoundError(path: string): AppError {
  return new AppError('NOT_FOUND', 'El recurso solicitado no existe.', { resource: path });
}

120→/**
 * Serialización **única** del envelope `{ error: { code, message, details? } }`
 * (HU-09-05 RN-1) sobre un `reply` de Fastify, con las cabeceras propias del error
 * (`Retry-After` en `RATE_LIMITED`, `Allow` en `METHOD_NOT_ALLOWED`). El status sale del
 * catálogo (`AppError.httpStatus`), nunca de la capa HTTP (RN-6).
 */
function sendAppError(reply: FastifyReply, error: AppError): void {
  for (const [header, value] of Object.entries(error.headers)) reply.header(header, value);
  reply.status(error.httpStatus).send(error.toEnvelope());
}
