 * El mismo envelope, serializado como respuesta HTTP **cruda**, para los client errors que
 * Node resuelve a nivel socket (`clientErrorHandler`), donde todavía no existe un `reply`
 * de Fastify. `Connection: close` porque el socket se destruye a continuación: la conexión
 * quedó en un estado del que el parser no puede recuperarse.
 */
function rawErrorResponse(error: AppError): string {
  const body = JSON.stringify(error.toEnvelope());
  const head = [
140→    `HTTP/1.1 ${error.httpStatus} ${STATUS_CODES[error.httpStatus] ?? 'Error'}`,
    'Content-Type: application/json; charset=utf-8',
    `Content-Length: ${Buffer.byteLength(body)}`,
    'Connection: close',
  ].join('\r\n');
  return `${head}\r\n\r\n${body}`;
}

export function buildApp(deps: AppDeps): FastifyInstance {
