   * Soporte CORS **opcional**, gobernado por `CORS_ALLOWED_ORIGINS`.
   *
   * No lo pide la spec (la superficie REST de HU-09-01 y su autenticación de HU-09-02 son
   * independientes del navegador); es configuración operativa para que el cliente web de la
   * épica 10 pueda correr en otro origen. Si la variable no está definida no se emite
   * **ningún** header de CORS y el servidor responde exactamente igual que sin la
   * funcionalidad.
   */
  const corsOrigins = deps.config.corsAllowedOrigins;

  /**
   * Headers de CORS de una respuesta **cualquiera** (incluidas las de error). Vive aparte del
   * hook `onRequest` porque los errores de framework se resuelven antes del ruteo, sin pasar
   * por ningún hook, y aun así el cliente web de la épica 10 tiene que poder leerlos.
   */
  const applyCorsHeaders = (request: FastifyRequest, reply: FastifyReply): void => {
    if (corsOrigins === null) return;
    // La respuesta depende del header `Origin` aunque el origen no esté permitido: se
    // declara siempre para que ninguna cache comparta una respuesta entre orígenes.
    reply.header('Vary', 'Origin');

    const origin = request.headers.origin;
    // Comparación **exacta** contra la lista configurada. Un origen no permitido no recibe
    // ningún header de CORS y el navegador bloquea la respuesta del lado del cliente; el
    // servidor no filtra nada extra (la autorización real la da el token, HU-09-02 RN-1).
    if (typeof origin !== 'string' || !corsOrigins.includes(origin)) return;

    // Eco del origen concreto, nunca `*`: la API viaja con credencial (`Authorization:
    // Bearer`) y un comodín sería incorrecto además de innecesario.
    reply.header('Access-Control-Allow-Origin', origin);
    // El cliente necesita leer `Retry-After` para respetar `RATE_LIMITED` (HU-09-02 RN-12).
    reply.header('Access-Control-Expose-Headers', 'Retry-After');
  };

  const app = Fastify({
    logger: { level: deps.config.logLevel },
    trustProxy: process.env.TRUST_PROXY === 'true',
    // Un cuerpo JSON mal formado no debe filtrar detalles internos: se traduce a
    // VALIDATION_ERROR en el error handler.
    bodyLimit: 1_048_576,
    routerOptions: {
      // `/api/v1/me/` y `/api/v1/me` son el **mismo** recurso: la barra final no cambia la
      // identidad del recurso ni el verbo soportado. Sin esta opción la ruta con barra no
      // matchea, cae en el 404-handler y `normalizePath` sí la reconoce como conocida, con lo
      // que un `GET /api/v1/me/` respondía un `METHOD_NOT_ALLOWED` cuyo `details.method`
      // estaba **dentro** de `details.allowed`: un 405 imposible por HU-09-01 RN-14 (el 405
      // describe un verbo *no* soportado) e inmanejable para el cliente (HU-09-05 RN-1/RN-4).
      // Con `ignoreTrailingSlash` la ruta resuelve normalmente y el 405 sólo aparece ante un
      // verbo realmente no permitido.
      ignoreTrailingSlash: true,
    },

/**
 * Rutas del cliente.
 *
 * El alcance de esta corrida es HU-10-01 (login), por eso sólo existen la ruta de login y la
 * ruta destino a la que el login navega (la vista de trading, HU-10-02, que se implementa en
 * otra corrida). No se agregan rutas fuera de alcance.
 */
export const LOGIN_ROUTE = '/login';
export const TRADING_ROUTE = '/trading';

