1→/**
 * Registro de cuentas e inicio de sesión (HU-01-01, HU-01-02).
 *
 * La precedencia de validación es determinista y se reporta **un solo error por respuesta**
 * (HU-01-01 RN-9, HU-01-02 RN-8; el paso 0 —rate limiting— lo aplica la capa HTTP antes de
 * llegar acá, incluso antes de la validación de esquema).
 */
import { randomUUID } from 'node:crypto';
import { AppError, validationError, type ValidationIssue } from '../shared/errors.js';
10→import { PASSWORD_MAX_LENGTH, PASSWORD_MIN_LENGTH } from '../config/index.js';
import type { Db } from '../infra/db.js';
import { isUniqueConstraintViolationOn } from '../infra/db.js';
import type { AuditLog } from '../shared/audit-log.js';
import { nowIso } from '../shared/time.js';
import { isValidEmailFormat, isValidEmailLength, normalizeEmail } from './email.js';
import { DUMMY_PASSWORD_HASH, hashPassword, verifyPassword } from './password.js';
import type { IssuedSession, SessionService } from './sessions.js';
import type { DepositAddressService } from '../wallet/deposit-address-service.js';

20→export type Account = {
  accountId: string;
  email: string;
  status: 'ACTIVE';
  createdAt: string;
};

type Credentials = { email: string; password: string };

function isPlainObject(value: unknown): value is Record<string, unknown> {
30→  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Paso 1 de la precedencia: esquema del payload.
 * HU-01-01 RN-4: el payload debe contener **exactamente** `email` (string) y `password`
 * (string); campo faltante, tipo incorrecto o campo desconocido ⇒ `VALIDATION_ERROR` (422).
 */
export function parseCredentialsPayload(
  body: unknown,
40→  options: { rejectUnknownFields: boolean },
): Credentials {
  if (!isPlainObject(body)) {
    throw validationError([{ message: 'El cuerpo de la solicitud debe ser un objeto JSON.' }]);
  }
  const issues: ValidationIssue[] = [];
  for (const field of ['email', 'password'] as const) {
    if (!(field in body) || body[field] === undefined) {
      issues.push({ field, message: `El campo "${field}" es requerido.` });
    } else if (typeof body[field] !== 'string') {
50→      issues.push({ field, message: `El campo "${field}" debe ser un string.` });
    }
  }
  if (options.rejectUnknownFields) {
    for (const key of Object.keys(body)) {
      if (key !== 'email' && key !== 'password') {
        issues.push({ field: key, message: `Campo desconocido "${key}".` });
      }
    }
  }
60→  if (issues.length > 0) throw validationError(issues);
  return { email: body.email as string, password: body.password as string };
}

export class AccountsService {
  constructor(
    private readonly db: Db,
    private readonly sessions: SessionService,
    private readonly depositAddresses: DepositAddressService,
    private readonly audit: AuditLog,
70→  ) {}

  findById(accountId: string): Account | null {
    const row = this.db
      .prepare(
        `SELECT account_id AS accountId, email, status, created_at AS createdAt
         FROM accounts WHERE account_id = ?`,
      )
      .get(accountId) as Account | undefined;
    return row ?? null;
80→  }

  /** HU-01-01: alta de cuenta. No emite token (RN-7: no hay auto-login). */
  async register(body: unknown, origin: string | null): Promise<Account> {
    // Paso 1 — esquema/tipos/campos requeridos y desconocidos.
    const { email: rawEmail, password } = parseCredentialsPayload(body, {
      rejectUnknownFields: true,
    });

    // Paso 2 — formato del email (sobre el email normalizado: trim + lowercase).
90→    const email = normalizeEmail(rawEmail);
    if (!isValidEmailLength(email)) {
      throw validationError([
        { field: 'email', message: 'El email no puede exceder 254 caracteres.' },
      ]);
    }
    if (!isValidEmailFormat(email)) {
      throw validationError([{ field: 'email', message: 'El email no tiene un formato válido.' }]);
    }

100→    // Paso 3 — política de contraseña.
    const passwordLength = [...password].length;
    if (passwordLength < PASSWORD_MIN_LENGTH || passwordLength > PASSWORD_MAX_LENGTH) {
      throw validationError([
        {
          field: 'password',
          message: `La contraseña debe tener entre ${PASSWORD_MIN_LENGTH} y ${PASSWORD_MAX_LENGTH} caracteres.`,
        },
      ]);
    }
110→
    // Paso 4 — unicidad del email normalizado. El hash del KDF se computa fuera de la
    // transacción (es costoso por diseño); la unicidad la garantiza el índice UNIQUE, que
    // resuelve también el caso de dos altas concurrentes (RN-8).
    const passwordHash = await hashPassword(password);
    const account: Account = {
      accountId: randomUUID(),
      email,
      status: 'ACTIVE',
      createdAt: nowIso(),
120→    };

    const create = this.db.transaction(() => {
      this.db
        .prepare(
          `INSERT INTO accounts (account_id, email, password_hash, status, created_at)
           VALUES (?, ?, ?, ?, ?)`,
        )
        .run(account.accountId, account.email, passwordHash, account.status, account.createdAt);
      // HU-06-03 RN-12: la asignación de la dirección de depósito es **eager** al alta; queda
130→      // en la misma transacción, de modo que toda cuenta existente es completa y consultable.
      this.depositAddresses.assign(account.accountId, { checkAccountExists: false });
    });

    try {
      create.immediate();
    } catch (error) {
      // Sólo la colisión del índice UNIQUE de `accounts.email` es EMAIL_ALREADY_EXISTS
      // (modelo-de-errores.md §3.6). Cualquier otra violación de constraint de la misma
      // transacción (p. ej. los índices UNIQUE de `deposit_addresses`) se propaga y el error
140→      // handler la traduce a INTERNAL_ERROR, sin inventar un `code` que no corresponde.
      if (isUniqueConstraintViolationOn(error, 'accounts.email')) {
        this.audit.record({
          event: 'REGISTER',
          email,
          result: 'FAILURE',
          reason: 'EMAIL_ALREADY_EXISTS',
          origin,
        });
        throw new AppError('EMAIL_ALREADY_EXISTS', 'Ya existe una cuenta con ese email.', { email });
150→      }
      throw error;
    }

    this.audit.record({
      event: 'REGISTER',
      email,
      accountId: account.accountId,
      result: 'SUCCESS',
      origin,
160→    });
    return account;
  }

  /**
   * HU-01-02: inicio de sesión.
   *
   * RN-11: el login **no** valida el formato del email (cualquier string pasa el esquema).
   * RN-2/RN-12: email inexistente y contraseña incorrecta son indistinguibles en respuesta y
   * en tiempo — cuando el email no existe se ejecuta un hash dummy de coste equivalente.
170→   */
  async login(body: unknown, origin: string | null): Promise<IssuedSession> {
    // Paso 1 — esquema/tipos. (No se rechazan campos desconocidos: agregar validaciones
    // propias del login abriría diferencias de respuesta explotables para enumerar cuentas.)
    const { email: rawEmail, password } = parseCredentialsPayload(body, {
      rejectUnknownFields: false,
    });

    // Paso 2 — verificación de credenciales.
    const email = normalizeEmail(rawEmail);
180→    const row = this.db
      .prepare('SELECT account_id AS accountId, password_hash AS passwordHash FROM accounts WHERE email = ?')
      .get(email) as { accountId: string; passwordHash: string } | undefined;

    const storedHash = row?.passwordHash ?? DUMMY_PASSWORD_HASH;
    const passwordOk = await verifyPassword(password, storedHash);

    if (row === undefined || !passwordOk) {
      this.audit.record({
        event: 'LOGIN',
190→        email,
        accountId: row?.accountId ?? null,
        result: 'FAILURE',
        reason: 'INVALID_CREDENTIALS',
        origin,
      });
      throw new AppError('INVALID_CREDENTIALS', 'Credenciales inválidas.');
    }

    const session = this.sessions.issue(row.accountId);
200→    this.audit.record({
      event: 'LOGIN',
      email,
      accountId: row.accountId,
      result: 'SUCCESS',
      origin,
    });
    return session;
  }
}
