() => {
  const raw = localStorage.getItem('exchange.web.session.v1');
  let session = null;
  try { session = raw ? JSON.parse(raw) : null; } catch {}
  const token = session && session.token;
  const html = document.documentElement.outerHTML;
  const url = location.href;
  return {
    url,
    hasToken: !!token,
    tokenLen: token ? token.length : 0,
    tokenInUrl: token ? url.includes(token) : null,
    tokenInDom: token ? html.includes(token) : null,
    tokenInLocalStorage: !!token,
    expiresAt: session && session.expiresAt,
    storageKeys: Object.keys(localStorage),
  };
}

