async (page) => {
  await page.unrouteAll({ behavior: 'ignoreErrors' }).catch(() => {});
  let loginPosts = [];
  await page.route('**/api/v1/auth/login', async (route) => {
    const req = route.request();
    if (req.method() === 'POST') {
      loginPosts.push({ url: req.url(), body: req.postData() });
      await new Promise((r) => setTimeout(r, 2500));
      await route.continue();
      return;
    }
    await route.continue();
  });
  await page.fill('#email', 'eval-web@test.local');
  await page.fill('#password', 'EvalWeb123!');
  // doble click en el mismo tick (anti doble submit RN-2)
  await page.evaluate(() => {
    const btn = document.querySelector('button[type=submit]');
    btn.click();
    btn.click();
  });
  const during = await page.evaluate(() => ({
    btnText: document.querySelector('button[type=submit]')?.textContent,
    disabled: document.querySelector('button[type=submit]')?.disabled,
    ariaBusy: document.querySelector('button[type=submit]')?.getAttribute('aria-busy'),
    url: location.href,
  }));
  // segundo intento desde Playwright mientras sigue in-flight
  let secondClick;
  try {
    await page.getByRole('button', { name: /Ingresar|Ingresando/ }).click({ timeout: 800 });
    secondClick = 'clicked';
  } catch (e) {
    secondClick = 'blocked: ' + String(e.message).split('\n')[0];
  }
  const afterSecondAttempt = await page.evaluate(() => ({
    btnText: document.querySelector('button[type=submit]')?.textContent,
    disabled: document.querySelector('button[type=submit]')?.disabled,
    url: location.href,
  }));
  return { loginPosts, during, secondClick, afterSecondAttempt };
}

